package com.jgeted.sagadyssey.social.war;

import com.jgeted.sagadyssey.social.war.api.*;
import com.jgeted.sagadyssey.social.war.application.WarMapService;
import java.util.*;
import java.util.concurrent.atomic.AtomicInteger;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

class WarMapServiceTest {
    static final UUID ACCOUNT=new UUID(0,1),ACTOR=new UUID(0,2),UNIT=new UUID(0,3),ARMY=new UUID(0,4);
    static final WarKey DIM=WarKey.parse("minecraft:overworld");
    static WarMapSheet sheet(){return new WarMapSheet(4,DIM,0,0,0);}
    static WarCommand.IssueOrder command(UUID actor){return new WarCommand.IssueOrder(UUID.randomUUID(),0,actor,ARMY,UNIT,1,new WarIntent(WarKey.parse("sagadyssey:war/order/hold"),1,new WarIntent.Position(DIM,10,65,10)));}
    static WarMapView.Receipt accepted(WarCommand.IssueOrder c){return new WarMapView.Receipt(WarMapView.Outcome.ACCEPTED,"ok",Optional.of(c.operationId()),105);}
    static WarMapView.Preview preview(WarMapService s,WarMapService.Lease l,long now){return s.prepare(l,command(ACTOR),WarMapView.Mode.HOLD,WarMapView.Delivery.DIRECT,5,now);}
    @Test void accountAndCurrentCharacterBothBindTheSession(){var s=new WarMapService();var l=s.open(ACCOUNT,ACTOR,sheet(),100);assertTrue(s.find(ACCOUNT,ACTOR,l.id(),100).isPresent());assertTrue(s.find(ACTOR,ACTOR,l.id(),100).isEmpty());assertTrue(s.find(ACCOUNT,ACCOUNT,l.id(),100).isEmpty());}
    @Test void expiryAndClockReversalCannotExtendAUserSession(){var s=new WarMapService();var l=s.open(ACCOUNT,ACTOR,sheet(),100);assertTrue(s.find(ACCOUNT,ACTOR,l.id(),1300).isPresent());assertTrue(s.find(ACCOUNT,ACTOR,l.id(),1301).isEmpty());assertTrue(s.find(ACCOUNT,ACTOR,l.id(),99).isEmpty());assertThrows(IllegalArgumentException.class,()->s.refresh(l,99));}
    @Test void reopeningTheSameAccountInvalidatesItsPreviousMapAndTicket(){var s=new WarMapService();var l=s.open(ACCOUNT,ACTOR,sheet(),100);preview(s,l,100);var newer=s.open(ACCOUNT,ACTOR,new WarMapSheet(5,DIM,0,0,0),101);assertTrue(s.find(ACCOUNT,ACTOR,l.id(),101).isEmpty());assertTrue(s.preview(newer,101).isEmpty());assertThrows(IllegalArgumentException.class,()->s.refresh(l,101));}
    @Test void previewsDoNotSubmitAndRepeatedConfirmationSubmitsOnce(){var s=new WarMapService();var l=s.open(ACCOUNT,ACTOR,sheet(),100);var p=preview(s,l,100);var calls=new AtomicInteger();assertEquals(0,calls.get());var first=s.issue(l,p.ticket(),100,c->{calls.incrementAndGet();return accepted(c);});assertEquals(first,s.issue(l,p.ticket(),101,c->{throw new AssertionError("must not replay");}));assertEquals(1,calls.get());assertTrue(s.preview(l,101).isEmpty());}
    @Test void refreshingAfterSubmissionRetainsTheOriginalReceiptAndNeverReplaysIt(){var s=new WarMapService();var l=s.open(ACCOUNT,ACTOR,sheet(),100);var p=preview(s,l,100);var first=s.issue(l,p.ticket(),100,WarMapServiceTest::accepted);var fresh=s.refresh(l,101);assertEquals(first,s.issue(fresh,p.ticket(),101,c->{throw new AssertionError("duplicate");}));}
    @Test void aRefreshInvalidatesAnUncommittedPreviewAndStaleLease(){var s=new WarMapService();var l=s.open(ACCOUNT,ACTOR,sheet(),100);var p=preview(s,l,100);var fresh=s.refresh(l,101);assertThrows(IllegalArgumentException.class,()->s.issue(l,p.ticket(),101,c->{throw new AssertionError();}));assertEquals(WarMapView.Outcome.REJECTED,s.issue(fresh,p.ticket(),101,c->{throw new AssertionError();}).outcome());}
    @Test void aReplacedOrExpiredPreviewCannotSubmit(){var s=new WarMapService();var l=s.open(ACCOUNT,ACTOR,sheet(),100);var p=preview(s,l,100);var next=preview(s,l,101);assertEquals(WarMapView.Outcome.REJECTED,s.issue(l,p.ticket(),101,c->{throw new AssertionError();}).outcome());assertEquals(WarMapView.Outcome.REJECTED,s.issue(l,next.ticket(),702,c->{throw new AssertionError();}).outcome());}
    @Test void readingTheTargetForTenSecondsStillAllowsExplicitConfirmation(){var s=new WarMapService();var l=s.open(ACCOUNT,ACTOR,sheet(),100);var p=preview(s,l,100);assertTrue(s.preview(l,300).isPresent());assertEquals(WarMapView.Outcome.ACCEPTED,s.issue(l,p.ticket(),300,WarMapServiceTest::accepted).outcome());}
    @Test void aLatePreviewCannotOutliveItsSession(){var s=new WarMapService();var l=s.open(ACCOUNT,ACTOR,sheet(),100);var p=preview(s,l,1290);assertEquals(l.expiresAt(),p.expiresAt());assertEquals(WarMapView.Outcome.ACCEPTED,s.issue(l,p.ticket(),1300,WarMapServiceTest::accepted).outcome());assertThrows(IllegalArgumentException.class,()->s.issue(l,p.ticket(),1301,c->{throw new AssertionError();}));}
    @Test void submissionExceptionsAreUnknownAndCannotTriggerAutomaticRetry(){var s=new WarMapService();var l=s.open(ACCOUNT,ACTOR,sheet(),100);var p=preview(s,l,100);var first=s.issue(l,p.ticket(),100,c->{throw new IllegalStateException("could have submitted");});assertEquals(WarMapView.Outcome.REVIEW,first.outcome());assertEquals(first,s.issue(l,p.ticket(),101,c->{throw new AssertionError("unsafe replay");}));}
    @Test void staleCloseCannotDeleteARefreshedSession(){var s=new WarMapService();var l=s.open(ACCOUNT,ACTOR,sheet(),100);var fresh=s.refresh(l,101);s.close(l);assertEquals(fresh,s.find(ACCOUNT,ACTOR,l.id(),101).orElseThrow());s.logout(ACCOUNT);assertTrue(s.find(ACCOUNT,ACTOR,l.id(),101).isEmpty());}
    @Test void aForeignActorCannotBePutIntoAnExistingPreview(){var s=new WarMapService();var l=s.open(ACCOUNT,ACTOR,sheet(),100);assertThrows(IllegalArgumentException.class,()->s.prepare(l,command(ACCOUNT),WarMapView.Mode.HOLD,WarMapView.Delivery.DIRECT,5,100));}
    @Test void anExpiredAttemptHasItsOwnFeedbackWithoutDestroyingThePriorSubmissionReceipt(){var s=new WarMapService();var l=s.open(ACCOUNT,ACTOR,sheet(),100);var p=preview(s,l,100);var accepted=s.issue(l,p.ticket(),100,WarMapServiceTest::accepted);var denied=s.issue(l,UUID.randomUUID(),101,c->{throw new AssertionError();});assertEquals(WarMapView.Outcome.REJECTED,denied.outcome());assertEquals(denied,s.receipt(l).orElseThrow());assertEquals(accepted,s.receipt(l,p.ticket()).orElseThrow());}
    @Test void aForeignOrderReceiptCannotBePresentedAsSuccessfulSubmission(){var s=new WarMapService();var l=s.open(ACCOUNT,ACTOR,sheet(),100);var p=preview(s,l,100);assertEquals(WarMapView.Outcome.REVIEW,s.issue(l,p.ticket(),100,c->new WarMapView.Receipt(WarMapView.Outcome.ACCEPTED,"foreign",Optional.of(UUID.randomUUID()),105)).outcome());}
    @Test void idleSessionsHaveABoundedCapacityAndExpiredEntriesCanBeReclaimed(){var s=new WarMapService();for(int i=0;i<256;i++)s.open(new UUID(0,i+10),ACTOR,sheet(),100);assertThrows(IllegalStateException.class,()->s.open(ACCOUNT,ACTOR,sheet(),100));assertNotNull(s.open(ACCOUNT,ACTOR,sheet(),1301));}
    @Test void everyMapScaleRoundTripsPixelsIncludingNegativeWorldCoordinates(){for(int scale=0;scale<=4;scale++){var s=new WarMapSheet(4,DIM,-512,768,scale);for(int p=0;p<128;p++){assertEquals(p,(int)Math.floor(s.pixelX(s.x(p))));assertEquals(p,(int)Math.floor(s.pixelZ(s.z(p))));}}}
    @Test void mapPixelsAndWorldBoundariesRejectOverflowOrArbitraryCoordinates(){var s=sheet();for(int p:new int[]{-1,128,Integer.MIN_VALUE,Integer.MAX_VALUE})assertThrows(IllegalArgumentException.class,()->s.x(p));assertThrows(IllegalArgumentException.class,()->new WarMapSheet(1,DIM,Integer.MAX_VALUE,0,0));assertThrows(IllegalArgumentException.class,()->new WarMapSheet(1,DIM,30_000_000,0,4).x(127));}
}
